import { useEffect, useState } from "react"
import Left from'../../shopingcart/src/Left'
import { useParams } from "react-router-dom"


function Adminupdateproduct() {
    const {id}=useParams()
    useEffect(()=>{
        fetch(`/api/singaldata/${id}`).then((resp)=>{ return resp.json()}).then((data)=>{
            console.log(data)
            if(data.status===200){
            setName(data.apiData.name)
            setDesc(data.apiData.desc)
            setMdesc(data.apiData.mdesc)
            setPrice(data.apiData.price)
            setQty(data.apiData.quantity)
            setStock(data.apiData.status)
            
            }else{
                setMessage(data.message)
            }
        })
    },[])
    
    const[name,setName]=useState('')
    const[desc,setDesc]=useState('')
    const[mdesc,setMdesc]=useState('')
    const[price,setPrice]=useState('')
    const[qty,setQty]=useState('')
    const[img,setImg]=useState('')
    const [message,setMessage]=useState('')

    function handleform(e){
        e.preventDefault()
    }


    return ( 
        <section>
            
              <div className="container">
            <div className="row">
             <Left/>
                <div className="col-md-8">
         

        <h2> procude data here</h2>
        <form onSubmit={(e)=>{handleform(e)}}>
        <label>name</label>
        <input type="text" className="form-control"
      value={name}
        />
        <label>desc</label>
        <textarea className="form-control"
         value={name}
        
        ></textarea>
        <label>mdesc</label>
        <textarea className="form-control"
        value={name}
        ></textarea>
        <label>price</label>
        <input type="number" className="form-control"
          value={name}
      
        />
            <label>qty</label>
    <input type="text" className="form-control"
   value={qty}
    />
    <label> product status</label>
    <select className="form-select">
        <option value="IN STOCK"> IN Stoce</option>
        <option value="OUT STOCK"> OUt Stoce</option>
    </select>
        <label>img</label>
        <input type="file" className="form-control"
      
        
        />
    
    <button type="submit" className="btn btn-info form-control">add</button>
  


        </form>
        </div>
        </div>
        </div>
        </section>
     );
}

export default Adminupdateproduct;
